import { createOpenAlexAdapter } from "./providers/openalex";
import { createEurostatAdapter } from "./providers/eurostat";
import { createLocalDocumentsAdapter } from "./providers/documents";

export const PROVIDER_SECRETS:Record<ResearchProviderId,SecretName[]> = {
  firecrawl:["firecrawl_api_key"], youtube:["youtube_api_key"], apify:["apify_api_token"], x:["x_bearer_token"],
  reddit:["reddit_client_id","reddit_client_secret","reddit_refresh_token"], openalex:["openalex_api_key"],
  tavily:["tavily_api_key"], eurostat:[],local_documents:[],
};
export function createResearchAdapters():Map<ResearchProviderId,ProviderAdapter> {
  return new Map([createFirecrawlAdapter(),createTavilyAdapter(),createYouTubeAdapter(),createXAdapter(),createRedditAdapter(),createApifyAdapter(),createOpenAlexAdapter(),createEurostatAdapter(),createLocalDocumentsAdapter()].map((adapter)=>[adapter.id,adapter]));
}
export interface ResearchCollectorOptions {
  settings: Settings;
  credentials: Partial<Record<SecretName,string>>;
  documents?: ProviderContext["documents"];
  adapters?: Map<ResearchProviderId,ProviderAdapter>;
  fetchImpl?:typeof fetch;
  save(dataset:ResearchDataset):Promise<void>;
}
export function createResearchCollector(options:ResearchCollectorOptions):ResearchCollector {
  return { async collect(input, context) {
    const request=ResearchRequest.parse(input);
    const signal=AbortSignal.any([context.signal,AbortSignal.timeout(request.limits.timeoutMs)]);
    const http=createProviderHttp({limits:request.limits,signal,fetchImpl:options.fetchImpl});
    const adapters=options.adapters??createResearchAdapters();
    const secrets=Object.values(options.credentials).filter((v):v is string=>!!v);
    const safe=(message:string)=>redactSecrets(message,secrets);
    const parts:ResearchDataset[]=[];
    let plannerRequests=0, totalRecords=0;
    const planner=options.settings.llm.provider==="anthropic"&&options.credentials.anthropic_api_key
      ?createMastraQueryPlanner({apiKey:options.credentials.anthropic_api_key,modelId:options.settings.llm.fastModel}):null;
    for(const [index,agentId] of [...new Set(request.agents)].entries()) {
      const definition=RESEARCH_AGENTS.find((d)=>d.id===agentId)!;
      const limitations:string[]=[];const sources:Source[]=[];const records:ResearchRecord[]=[];
      const states:string[]=[];const startRequests=http.requests+plannerRequests;
      let queries=buildQueries(agentId,request.scope);
      try {
        if (planner) {
          if(http.requests+plannerRequests>=request.limits.maxRequests) throw new Error("Shared request limit prevents Mastra query planning.");
          plannerRequests++;
          queries=await withAbort(planner(agentId,request.scope,signal),signal);
        }
        for(const originalProvider of definition.providers) {
          const provider=originalProvider==="firecrawl"&&options.settings.research.provider==="tavily"?"tavily":originalProvider;
          const config=options.settings.research.apis[provider];
          if(!config.enabled){states.push("blocked");limitations.push(`${provider}: disabled in Research APIs Settings.`);continue;}
          if((provider==="reddit"||provider==="apify")&&config.approval!=="granted"){states.push("blocked");limitations.push(`${provider}: usage approval not granted.`);continue;}
          if(provider!=="openalex"&&PROVIDER_SECRETS[provider].some((name)=>!options.credentials[name])){states.push("missing_credentials");limitations.push(`${provider}: required credentials are missing.`);continue;}
          if(signal.aborted){states.push("cancelled");limitations.push("Research cancelled or time limit reached.");break;}
          const remaining=request.limits.maxResults-totalRecords;
          if(remaining<=0){states.push("partial");limitations.push("Shared result limit reached.");break;}
          const adapter=adapters.get(provider);
          if(!adapter){states.push("blocked");limitations.push(`${provider}: adapter not installed.`);continue;}
          try {
            const outcome=await adapter.collect({agentId,scope:request.scope,queries}, {
              http,credentials:options.credentials,config,
              limits:{...request.limits,maxResults:remaining,maxRequests:Math.max(1,request.limits.maxRequests-plannerRequests)},
              signal,log:(message)=>context.log(safe(message)),now:()=>new Date().toISOString(),documents:options.documents,
            });
            states.push(outcome.status);limitations.push(...outcome.limitations.map(safe));
            for(const value of outcome.items.slice(0,remaining)) {
              const item=CollectedItem.parse(value);
              const {source,record}=normalizeItem(item,agentId,context.runId,new Date().toISOString());
              sources.push(source);records.push(record);totalRecords++;
            }
          } catch(error) {
            const failure=errorReport(error);
            states.push(signal.aborted?"cancelled":failure.code==="invalid_credentials"?"missing_credentials":failure.code==="permission_required"||failure.code==="unsupported"?"blocked":"error");
            limitations.push(`${provider}: ${safe(failure.message)}`);
          }
        }
      } catch(error) {states.push(signal.aborted?"cancelled":"error");limitations.push(signal.aborted?"Research cancelled or time limit reached.":"Mastra query planning failed; no fabricated queries or results used.");}
      const status:AgentCollectionResult["status"]=signal.aborted?"cancelled":records.length?(states.some((s)=>s!=="success"&&s!=="empty")?"partial":"success"):
        states.includes("error")?"error":states.includes("missing_credentials")?"missing_credentials":states.includes("blocked")?"blocked":states.includes("partial")?"partial":"empty";
      const result:AgentCollectionResult={agentId,status,recordIds:[...new Set(records.map((r)=>r.id))],limitations:[...new Set(limitations)],requests:http.requests+plannerRequests-startRequests};
      const dataset=ResearchDataset.parse({schemaVersion:1,runId:context.runId,sources,records,results:[result],retrievedAt:new Date().toISOString(),synthetic:false});
      parts.push(dataset);
      await options.save(mergeResearchDatasets(...parts));
      context.log(`${definition.label}: ${status}, ${result.recordIds.length} original records.`);
      context.progress((index+1)/request.agents.length);
    }
    return mergeResearchDatasets(...parts);
  }};
}
