// Owner: WS6 — the Research block: web research → a data stream in the same format as Raw.
export const researchImplementations: BlockImplementation<"research">[] = [defineBlock({
  kind:"research",
  async run(_inputs,params,ctx) {
    if(!ctx.research) throw new Error("Research runtime is not configured in the main process.");
    let advanced:unknown;
    try {advanced=JSON.parse(typeof params.scopeJson==="string"?params.scopeJson:"{}");}catch {throw new Error("Advanced research scope must be valid JSON.");}
    if(!advanced||typeof advanced!=="object"||Array.isArray(advanced))throw new Error("Advanced research scope must be a JSON object.");
    const from=new Date();from.setUTCMonth(from.getUTCMonth()-Number(params.maxAgeMonths??24));
    const document=FileRef.nullable().parse(params.document??null);
    const scope=ResearchScope.parse({brand:"BMW",model:ctx.scope.vehicleLine,derivative:ctx.scope.derivative,
      markets:[params.market==="global"||!params.market?ctx.scope.market:params.market],horizonYears:ctx.scope.horizonYears,
      questions:typeof params.question==="string"&&params.question.trim()?[params.question]:[],
      allowedDomains:ctx.settings.research.allowedDomains,blockedDomains:ctx.settings.research.blockedDomains,
      publishedFrom:from.toISOString().slice(0,10),...(document?{documentIds:[document.fileId]}:{}),...advanced,
    });
    const request=ResearchRequest.parse({scope,agents:Array.isArray(params.agents)&&params.agents.length?params.agents:RESEARCH_AGENT_IDS,
      limits:{maxResults:params.maxResults??10,maxRequests:params.maxRequests??100,maxDocumentPages:params.maxDocumentPages??20,timeoutMs:params.timeoutMs??120000,concurrency:params.concurrency??3}});
    const dataset=await ctx.research.collect(request,{runId:ctx.runId,signal:ctx.signal,log:ctx.log,progress:ctx.progress});
    return {status:"ok",outputs:{out:{...emptyPipelineData(),sources:dataset.sources,records:dataset.records}}};
  },
})];
