+// Deliberately recognizable reversible fake cipher; this does NOT test OS keyring encryption.
+const cipherPrefix = "synthetic-cipher:v1:";
+const syntheticKey = "synthetic-private-firecrawl-credential";
+const syntheticText = "Synthetic publication: deliveries are 7.\nSynthetic strategy statement remains verbatim.\n舒适 — unchanged.\n";
+function secureStorage(): SecureStorage {
+  return {
+    isEncryptionAvailable: () => true,
+    getSelectedStorageBackend: () => "synthetic-keyring",
+    encryptString: (value) => Buffer.concat([Buffer.from(cipherPrefix), Buffer.from([...Buffer.from(value)].map((byte) => byte ^ 0xa5))]),
+    decryptString: (value) => {
+      if (!value.subarray(0, cipherPrefix.length).equals(Buffer.from(cipherPrefix))) throw new Error("Synthetic corrupt cipher");
+      return Buffer.from([...value.subarray(cipherPrefix.length)].map((byte) => byte ^ 0xa5)).toString("utf8");
+    },
+  };
+}
+function deferred<T>() {
+  let resolve!: (value: T) => void;
+  const promise = new Promise<T>((done) => { resolve = done; });
+  return { promise, resolve };
+}
+const emptySearch = () => Response.json({ success: true, data: { web: [] } });
+const config = (overrides: Partial<ResearchProviderConfig> = {}) => ResearchProviderConfig.parse({ enabled: true, ...overrides });
+function researchBlock(id: string, overrides: BlockParams = {}): WorkflowBlock {
+  return { ...createBlock("research", { id, position: { x: 0, y: 0 } }), params: { ...defaultBlockParams("research"), ...overrides } };
+}
